const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const base=path.resolve(__dirname,'../../source/ord-unit-probe/wwwroot');
const Graph=require(path.join(base,'recipe-graph.js')),Strategy=require(path.join(base,'nightmare-strategy.js'));
const hash='a'.repeat(64),passed=[],failures=[];function test(name,fn){try{fn();passed.push(name);}catch(error){failures.push({name,error:error.message});}}
const unit=(rawcode,tier='전설')=>({rawcode,displayName:rawcode,tier,playable:true});
const recipe=(id,result,needs,conditions=[])=>({id,resultUnitRawcode:result,resultCount:1,ingredients:[...Object.entries(needs).map(([rawcode,count])=>({type:'UNIT',rawcode,count})),...conditions]});
const effect=(kind,value,target='enemy',extra={})=>({kind,value,target,mode:'always',scope:'area',conditions:[],evidence:{type:'tooltip',quote:'fixture native evidence'},...extra});
const profile=(mode,effects=[])=>({verified:true,verificationKind:'native',damage:{reviewedAnchorRole:mode?mode+'Dps':null,primaryType:mode,explicitTypes:mode?[mode]:[]},effects});
function fixture(){
 const catalog={map:{sha256:hash},units:['h001','h002','h003','h004','h005','h009'].map(c=>unit(c,'흔함')).concat(['p001','m001','o001'].map(c=>unit(c,'초월')),['c001','c002','n001','r001','a001','b001','q001','i001','i002'].map(c=>unit(c))),recipes:[
  recipe('R100','m001',{h009:20}),recipe('R101','p001',{h009:18}),recipe('R102','c001',{h001:1}),recipe('R103','c002',{h002:1}),recipe('R104','n001',{h002:1}),recipe('R105','r001',{h003:1}),recipe('R106','a001',{h004:1}),recipe('R107','b001',{h005:1}),recipe('R108','q001',{h001:1})]};
 const source={file:'native',lines:[1],quote:'source'};
 const purpose={lineDamage:{assessment:'main',evidence:[source],conditions:[]},bossDamage:{assessment:'main',evidence:[source],conditions:[]},storyDamage:{assessment:'support',evidence:[source],conditions:[]}};
 const combat={map:{sha256:hash},units:{m001:profile('magic'),p001:profile('physical'),o001:profile('magic'),c001:profile(null,[effect('slow',30),effect('stun',2,'enemy',{chancePercent:20,durationSeconds:2})]),c002:profile(null,[effect('slow',40),effect('stun',3)]),n001:profile(null,[effect('manaRegeneration',1.5,'ally')]),r001:profile(null,[effect('magicResistanceReduction',20)]),a001:profile(null,[effect('magicAmplification',20)]),b001:profile(null,[effect('attackSpeedBuff',30,'ally')]),q001:profile(null,[effect('stun',10)])},curatedStrategyProfiles:{schemaVersion:1,units:{m001:{primaryRole:'magicDps',...purpose,manaDependence:{usesManaSkills:true,costs:[{thresholdMana:135,consumedMana:135,source}],regeneration:[],cycleEvaluation:{status:'conditional_inputs_only'}}},p001:{primaryRole:'physicalDps',...purpose,manaDependence:{usesManaSkills:false,costs:[]}},o001:{primaryRole:'magicDps',...purpose,manaDependence:{usesManaSkills:true,costs:[]}},c001:{primaryRole:'controlSupport'},c002:{primaryRole:'controlSupport'},n001:{primaryRole:'manaSupport'},r001:{primaryRole:'magicSupport'},a001:{primaryRole:'magicSupport'},b001:{primaryRole:'attackSupport'}},deckTemplates:[
  {id:'magic-a',name:'fixed magic roster',direction:'magic',coreRawcodes:['m001'],supportSlots:[{id:'control',roles:['control'],preferredRawcodes:['c001'],alternatives:['c002'],count:1},{id:'mana',roles:['manaSupport'],preferredRawcodes:['n001'],count:1},{id:'resist',roles:['magicResistanceReduction'],preferredRawcodes:['r001'],count:1},{id:'amp',roles:['magicAmplification'],preferredRawcodes:['a001'],count:1},{id:'buff',roles:['attackSpeedBuff'],preferredRawcodes:['b001'],count:1}],requiredCoverage:['lineDamage','bossDamage','storyDamage','manaSupport','magicResistanceReduction','magicAmplification','control'],evidenceScope:'native_composition_not_verified_clear'},
  {id:'physical-a',name:'fixed physical roster',direction:'physical',coreRawcodes:['p001'],supportSlots:[{id:'control',preferredRawcodes:['c001'],alternatives:['c002']}],requiredCoverage:['lineDamage'],evidenceScope:'native_composition_not_verified_clear'}]}};
 return {catalog,combat,rules:{map:{sha256:hash},completion:{canConfirmClear:false,structuralRequirements:[],numericRequirements:[{role:'line_clearance',verified:false}],unresolved:['runtime enemy defense unknown']}}};
}
const settings={recipeConditionsSupported:true,readableConditionTypes:['UBAN','KING'],itemRequirementsSupported:true,readableItemRawcodes:['AI00','AI01','AI02'],allowChoiceWisps:true,wood:30,maxMilliseconds:1000,maxSearchNodes:10000};
const make=f=>{const engine=Strategy.create(f.catalog,f.combat,f.rules);return {recommend:(stock,opts)=>engine.recommend(stock,{supportedRecipeIds:f.catalog.recipes.map(r=>r.id),...opts})};};
function replay(action,catalog,initial){
 const stock=new Map(Object.entries(initial)),recipes=new Map(catalog.recipes.map(r=>[r.id,r]));
 for(const entry of action.expectedSteps){const step=entry.type==='choice'?{resultUnitRawcode:entry.resultRawcode,resultCount:1,ingredients:[{type:'UNIT',rawcode:'e018',count:1}]}:recipes.get(entry.recipeId);assert(step);
  for(const i of step.ingredients.filter(i=>i.type==='UNIT')){assert((stock.get(i.rawcode)||0)>=i.count);stock.set(i.rawcode,(stock.get(i.rawcode)||0)-i.count);}
  stock.set(step.resultUnitRawcode,(stock.get(step.resultUnitRawcode)||0)+step.resultCount);
  for(const [code,count]of Object.entries(action.protectedCounts))assert((stock.get(code)||0)>=count);
 }
 assert.deepEqual(Object.fromEntries([...stock].filter(([,n])=>n>0)),action.expectedFinalCounts);
}
test('resource shortage keeps the complete fixed roster and never calls it ready',()=>{
 const f=fixture(),r=make(f).recommend({o001:1,h001:1,h002:1,e018:8},settings),d=r.targetDeck;
 assert.equal(d.id,'magic-a');assert.equal(d.goals.length,7);assert(d.goals.some(g=>g.rawcode==='m001'));assert(d.goals.some(g=>g.rawcode==='n001'));assert(!d.planning.current.unitReady);assert(d.planning.forecast.available);assert(d.planning.forecast.choiceDeficit>0);assert(!d.assessment.canConfirmClear);assert.equal(d.assessment.clearStatus,'unverified');
});
test('line boss story mana synergy and control are separate requirements',()=>{
 const f=fixture(),r=make(f).recommend({o001:1,h001:1,e018:8},settings),d=r.targetDeck;
 for(const role of ['lineDamage','bossDamage','storyDamage','manaSupport','magicResistanceReduction','magicAmplification','alwaysSlow','areaStun'])assert(d.requirements.some(q=>q.role===role));
 assert(d.assessment.mana.some(m=>m.rawcode==='m001'&&m.usesManaSkills));assert(d.assessment.mana.some(m=>m.rawcode==='o001'));assert(d.requirements.every(q=>q.nativeMandatory===false));
});
