test('missing random ITEM goals rank behind reachable goals but remain conditional when no reachable alternative exists',()=>{
 const f=feasibilityFixture();f.combat.units.p001.effects.push(effect('armorReduction',20));f.catalog.recipes[0].ingredients.push({type:'ITEM',rawcode:'AI00',count:1});const e=make(f),o={...feasibilitySettings,items:itemState()},before=e.recommend(feasibilityArmy,o),conditional=before.alternatives.find(d=>d.id==='magic-a');assert.equal(before.selectedDeckId,'physical-a');assert.equal(conditional.recommendationFeasibility.status,'conditional');assert(conditional.recommendationFeasibility.reasons.includes('random_item_missing'));const only=make(f).recommend(feasibilityArmy,{...o,direction:'magic'});assert(only.targetDeck);assert.equal(only.targetDeck.recommendationFeasibility.grade,'B');assert(!only.targetDeck.planning.forecast.available);assert(!only.goalCraftTargets.find(g=>g.towardRawcode==='m001').available);assert(!only.targetDeck.goals.find(g=>g.rawcode==='m001').progress.itemsReady);const acquired=e.recommend(feasibilityArmy,{...o,preferredDeckId:before.selectedDeckId,items:itemState({AI00:1})});assert.equal(acquired.selectedDeckId,'magic-a');assert.equal(acquired.targetDeck.recommendationFeasibility.status,'reachable');
});
test('all hard-blocked automatic candidates return no goal or actions while retaining inspectable alternatives',()=>{
 const f=feasibilityFixture();for(const r of f.catalog.recipes.filter(r=>['m001','p001'].includes(r.resultUnitRawcode)))r.ingredients.push({type:'UBAN',rawcode:r.resultUnitRawcode,count:1});const r=make(f).recommend(feasibilityArmy,{...feasibilitySettings,recipeConditions:nativeConditions({m001:true,p001:true})});assert.equal(r.targetDeck,null);assert.equal(r.selectedDeckId,null);assert.deepEqual(r.order,[]);assert.deepEqual(r.craftTargets,[]);assert.deepEqual(r.goalCraftTargets,[]);assert.equal(r.alternatives.length,2);assert(r.alternatives.every(d=>d.recommendationFeasibility.status==='blocked'));assert(r.feasibilitySelection.noEligibleAutomaticTarget);
});
test('explicit and legacy manual choices preserve blocked targets and running automatic choices wait until idle',()=>{
 const f=feasibilityFixture();f.catalog.recipes[0].ingredients.push({type:'UBAN',rawcode:'m001',count:1});for(const manual of [true,undefined]){const r=make(f).recommend(feasibilityArmy,{...feasibilitySettings,preferredDeckId:'magic-a',manualDeckChoice:manual,recipeConditions:nativeConditions({m001:true})});assert.equal(r.selectedDeckId,'magic-a');assert.equal(r.targetDeck.recommendationFeasibility.status,'blocked');assert(!r.goalCraftTargets.find(g=>g.towardRawcode==='m001').available);}const e=make(f),o={...feasibilitySettings,sessionIdentity:'busy-hard-condition'},before=e.recommend(feasibilityArmy,{...o,recipeConditions:nativeConditions({m001:false})}),busy=e.recommend(feasibilityArmy,{...o,preferredDeckId:before.selectedDeckId,craftRunning:true,activeCraftTarget:'m001',recipeConditions:nativeConditions({m001:true})});assert.equal(busy.selectedDeckId,'magic-a');assert.equal(busy.targetDeck.recommendationFeasibility.status,'blocked');assert.deepEqual(busy.craftTargets,[]);assert(busy.recipeConditionReevaluation.pending);const idle=e.recommend(feasibilityArmy,{...o,preferredDeckId:before.selectedDeckId,craftRunning:false,recipeConditions:nativeConditions({m001:true})});assert.equal(idle.selectedDeckId,'physical-a');assert(idle.recipeConditionReevaluation.performed);
});
test('unknown remaining rewards leave ordinary-unit choice and currency shortages conditional',()=>{
 const f=feasibilityFixture();f.catalog.recipes[0]=recipe('R100','m001',{l001:1,h009:100},[{type:'WOOD',count:50},{type:'GOLD',count:1000}]);const r=make(f).recommend({l001:1},{...feasibilitySettings,direction:'magic',wood:0,gold:0});assert(r.targetDeck);assert.equal(r.targetDeck.recommendationFeasibility.status,'conditional');assert.equal(r.targetDeck.budgetFeasibility.status,'unknown');assert(!r.targetDeck.planning.current.unitReady);assert(r.targetDeck.planning.forecast.available);assert(r.targetDeck.planning.forecast.choiceDeficit>0);assert.equal(r.craftTargets.length,0);
});
test('a blocked first recipe never hides an allowed alternative needing an ordinary future acquisition',()=>{
 const f=feasibilityFixture();f.catalog.units.push(unit('x001','희귀'));f.catalog.recipes[0]=recipe('R100','m001',{l001:1,h009:1},[{type:'UBAN',rawcode:'m001',count:1}]);f.catalog.recipes.push(recipe('ZALT','m001',{l001:1,x001:1,h009:1}));const r=make(f).recommend(feasibilityArmy,{...feasibilitySettings,direction:'magic',recipeConditions:nativeConditions({m001:true})});assert(r.targetDeck);assert.notEqual(r.targetDeck.recommendationFeasibility.status,'blocked');assert(r.targetDeck.recommendationFeasibility.diagnosed);assert.equal(r.targetDeck.planning.forecast.reason,'recipe_conditions_blocked');assert(!r.goalCraftTargets.find(g=>g.towardRawcode==='m001').available);
});
