 const f=feasibilityFixture();f.catalog.units.push(unit('z001','특별'));f.combat.acquisitionModel={randomOnlyRawcodes:['z001']};f.catalog.recipes[0]=recipe('R100','m001',{l001:1,z001:1,h009:1},[{type:'ITEM',rawcode:'AI00',count:1}]);const r=make(f).recommend(feasibilityArmy,{...feasibilitySettings,direction:'magic',items:{status:'unknown'}});assert.equal(r.targetDeck,null);const blocked=r.alternatives.find(d=>d.id==='magic-a');assert.equal(blocked.planning.forecast.reason,'items_unknown');assert.equal(blocked.recommendationFeasibility.status,'blocked');assert(blocked.recommendationFeasibility.reasons.includes('unowned_random_only_material'));assert.deepEqual(r.craftTargets,[]);
